<?php defined('_JEXEC') or die;$markers=[];$now=time();foreach($this->items as $row){if($row['latitude']!==null&&$row['session_id']!==null)$markers[]=['lat'=>(float)$row['latitude'],'lng'=>(float)$row['longitude'],'title'=>$row['display_name'],'status'=>$row['dispatch_status']??'online','recordedAt'=>$row['recorded_at']];} ?><div class="container-fluid kaar-booking"><div class="d-flex justify-content-between align-items-center"><h1>Live Trips &amp; Driver Locations</h1><span class="text-muted">Refreshes every 30 seconds</span></div><?php if($this->mapsKey!==''&&$markers): ?><div id="kaar-live-map" style="height:480px;min-height:320px" class="border rounded mb-4" aria-label="Map of online drivers"></div><script>window.kaarDriverMarkers=<?php echo json_encode($markers,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;window.initKaarDriverMap=()=>{const rows=window.kaarDriverMarkers||[];const map=new google.maps.Map(document.getElementById('kaar-live-map'),{center:rows[0],zoom:12});const bounds=new google.maps.LatLngBounds();rows.forEach(r=>{const p={lat:r.lat,lng:r.lng};bounds.extend(p);new google.maps.Marker({map,position:p,title:r.title+' — '+r.status});});if(rows.length>1)map.fitBounds(bounds);};setTimeout(()=>location.reload(),30000);</script><script async defer src="https://maps.googleapis.com/maps/api/js?key=<?php echo rawurlencode($this->mapsKey); ?>&callback=initKaarDriverMap"></script><?php else: ?><div class="alert alert-info">Configure a Google Maps browser key in Kaar Booking Options to display the map. The location table remains available.</div><script>setTimeout(()=>location.reload(),30000);</script><?php endif; ?><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Driver</th><th>Login</th><th>Ride</th><th>Vehicle</th><th>Location</th><th>Accuracy</th><th>Last report</th><th>Freshness</th></tr></thead><tbody><?php foreach($this->items as $row): $stale=empty($row['recorded_at'])||($now-strtotime($row['recorded_at'])>$this->staleMinutes*60); ?><tr><td><?php echo htmlspecialchars($row['display_name'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo $row['session_id']?'Authenticated':'No active session'; ?></td><td><?php echo htmlspecialchars(($row['reference']??'—').' '.($row['dispatch_status']??''),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($row['registration_number']??'—',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo $row['latitude']!==null?htmlspecialchars($row['latitude'].', '.$row['longitude'],ENT_QUOTES,'UTF-8'):'No report'; ?></td><td><?php echo $row['accuracy_m']!==null?(float)$row['accuracy_m'].' m':'—'; ?></td><td><?php echo htmlspecialchars($row['recorded_at']??'—',ENT_QUOTES,'UTF-8'); ?></td><td><span class="badge <?php echo $stale?'bg-warning text-dark':'bg-success'; ?>"><?php echo $stale?'Stale':'Live'; ?></span></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="8">No online logged-in drivers.</td></tr><?php endif; ?></tbody></table></div></div>
